// src/components/layout/sidebar.tsx
'use client';

import {
  Home, ShoppingBag, ListOrdered, Heart, Wallet, Settings, LogOut
} from 'lucide-react';
import Link from 'next/link';

const menuItems = [
  { icon: Home, text: 'Home', href: '/' },
  { icon: ShoppingBag, text: 'Shopping', href: '#' },
  { icon: ListOrdered, text: 'Order List', href: '#' },
  { icon: Heart, text: 'Favorite', href: '#' },
  { icon: Wallet, text: 'Payment', href: '#' },
  { icon: Settings, text: 'Settings', href: '#' },
];

const Sidebar = () => {
  return (
    <aside className="w-64 bg-white p-6 flex flex-col justify-between">
      <div>
        <h1 className="text-2xl font-bold mb-10 ml-4">N</h1>
        <nav>
          <ul>
            {menuItems.map((item, index) => (
              <li key={index}>
                <Link href={item.href} 
                   className={`flex items-center py-3 px-4 rounded-lg transition-colors
                   ${item.text === 'Home' ? 'bg-brand-primary text-black font-semibold' : 'text-brand-text-secondary hover:bg-gray-100'}`}>
                  <item.icon className="w-5 h-5 mr-3" />
                  {item.text}
                </Link>
              </li>
            ))}
          </ul>
        </nav>
      </div>
      <div>
         <Link href="#" className="flex items-center py-3 px-4 rounded-lg text-brand-text-secondary hover:bg-gray-100">
            <LogOut className="w-5 h-5 mr-3" />
            Log Out
         </Link>
      </div>
    </aside>
  );
};

export default Sidebar;